-- ───────────────────────── part 2 — raw SQL (ADR-002)

-- ADR-100: several supervisors per team. Copy the single-supervisor history (every row was the
-- primary), then open a primary row for any live team that has none (defensive).
INSERT INTO team_supervisors (team_id, user_id, is_primary, valid_from, valid_to, added_by, reason, created_at)
SELECT h.team_id, h.supervisor_id, true, h.valid_from, h.valid_to, h.changed_by, h.reason, h.created_at
  FROM team_supervisor_history h;

INSERT INTO team_supervisors (team_id, user_id, is_primary, valid_from, added_by, reason)
SELECT t.id, t.supervisor_id, true, CURRENT_TIMESTAMP, NULL, 'A9 migration'
  FROM teams t
 WHERE t.status <> 'ARCHIVED'
   AND NOT EXISTS (SELECT 1 FROM team_supervisors s WHERE s.team_id = t.id AND s.valid_to IS NULL);

ALTER TABLE team_supervisors
  ADD CONSTRAINT team_supervisors_interval_chk CHECK (valid_to IS NULL OR valid_to > valid_from);

-- One open row per (team, user): a person leads a team once at a time.
CREATE UNIQUE INDEX team_supervisors_one_open_uq
  ON team_supervisors (team_id, user_id)
  WHERE valid_to IS NULL;

-- At most one open primary per team (the service keeps "exactly one" for live teams).
CREATE UNIQUE INDEX team_supervisors_one_primary_uq
  ON team_supervisors (team_id)
  WHERE is_primary AND valid_to IS NULL;

-- New leadership rows must name a SUPERVISOR (closed historic rows were copied above, before the trigger).
CREATE OR REPLACE FUNCTION team_supervisors_role_fn() RETURNS trigger AS $$
BEGIN
  IF NEW.valid_to IS NULL AND NOT EXISTS (SELECT 1 FROM users u WHERE u.id = NEW.user_id AND u.role = 'SUPERVISOR') THEN
    RAISE EXCEPTION 'NOT_A_SUPERVISOR' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER team_supervisors_role_trg
  BEFORE INSERT OR UPDATE OF user_id ON team_supervisors
  FOR EACH ROW EXECUTE FUNCTION team_supervisors_role_fn();

-- ADR-101: at most one open worker foreman per team.
CREATE UNIQUE INDEX team_memberships_one_foreman_uq
  ON team_memberships (team_id)
  WHERE role = 'FOREMAN' AND valid_to IS NULL;

-- The foreman is a member record only: never linked to a login account in this version.
CREATE OR REPLACE FUNCTION team_memberships_foreman_no_user_fn() RETURNS trigger AS $$
BEGIN
  IF NEW.role = 'FOREMAN' AND NEW.valid_to IS NULL
     AND EXISTS (SELECT 1 FROM team_members m WHERE m.id = NEW.member_id AND m.user_id IS NOT NULL) THEN
    RAISE EXCEPTION 'FOREMAN_HAS_ACCOUNT' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER team_memberships_foreman_no_user_trg
  BEFORE INSERT OR UPDATE OF role, valid_to ON team_memberships
  FOR EACH ROW EXECUTE FUNCTION team_memberships_foreman_no_user_fn();

CREATE OR REPLACE FUNCTION team_members_user_not_foreman_fn() RETURNS trigger AS $$
BEGIN
  IF NEW.user_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM team_memberships tm
                  WHERE tm.member_id = NEW.id AND tm.role = 'FOREMAN' AND tm.valid_to IS NULL) THEN
    RAISE EXCEPTION 'FOREMAN_HAS_ACCOUNT' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER team_members_user_not_foreman_trg
  BEFORE UPDATE OF user_id ON team_members
  FOR EACH ROW EXECUTE FUNCTION team_members_user_not_foreman_fn();

-- ADR-102: organisational structure. Cycles across several rows are checked in the service
-- (advisory lock); the CHECKs catch the one-row case.
ALTER TABLE org_units
  ADD CONSTRAINT org_units_not_own_parent_chk CHECK (parent_id IS NULL OR parent_id <> id),
  ADD CONSTRAINT org_units_name_chk CHECK (length(btrim(name)) > 0);

CREATE UNIQUE INDEX org_units_code_uq
  ON org_units (lower(code))
  WHERE code IS NOT NULL AND archived_at IS NULL;

ALTER TABLE org_positions
  ADD CONSTRAINT org_positions_one_holder_chk CHECK (NOT (holder_user_id IS NOT NULL AND holder_member_id IS NOT NULL)),
  ADD CONSTRAINT org_positions_not_self_chk CHECK (reports_to_position_id IS NULL OR reports_to_position_id <> id),
  ADD CONSTRAINT org_positions_title_chk CHECK (length(btrim(title)) > 0);

-- ADR-103: violations without a person. Old rows keep their single snapshot supervisor.
UPDATE violations
   SET supervisor_ids_snapshot = CASE WHEN supervisor_id_snapshot IS NULL THEN ARRAY[]::uuid[]
                                      ELSE ARRAY[supervisor_id_snapshot] END;

ALTER TABLE violations
  ADD CONSTRAINT violations_expected_person_chk CHECK (expected_person_photos BETWEEN 0 AND 1),
  ADD CONSTRAINT violations_assigned_chk CHECK (assigned_at IS NULL OR member_id IS NOT NULL),
  -- an unassigned violation has no team snapshot (the snapshot follows the person)
  ADD CONSTRAINT violations_unassigned_no_team_chk CHECK (member_id IS NOT NULL OR team_id_snapshot IS NULL);

-- The "unassigned" KPI and the assigned=false filter.
CREATE INDEX violations_unassigned_idx
  ON violations (captured_at)
  WHERE member_id IS NULL;

-- ADR-104: OCR job state.
ALTER TABLE violation_ocr
  ADD CONSTRAINT violation_ocr_attempts_chk CHECK (attempts >= 0),
  ADD CONSTRAINT violation_ocr_done_chk CHECK (status <> 'DONE' OR extracted_at IS NOT NULL);
